SELECT jsonb_build_object(
    'rows', count(*),
    'affected', count(${_column}),
    'deleted', count(*) FILTER (WHERE ${_column} IS NOT NULL AND deleted != 0)
)::text
FROM ${_schema}.${_table}




SELECT count(*) FILTER (WHERE ${_table}.${_column} IS NOT NULL AND


            CASE WHEN jsonb_typeof(${_table}.${_column}) = 'array' THEN EXISTS (
                SELECT 1 FROM jsonb_array_elements_text(${_table}.${_column}) item(value)
                WHERE NOT (CAST(#{validValues} AS jsonb) ? item.value)
            ) ELSE false END

        NOT (CAST(#{validValues} AS jsonb) ? ${_table}.${_column}::text)

) FROM ${_schema}.${_table}

mapper.update:




ALTER TABLE ${_schema}.${_table}
    ALTER COLUMN ${_column} DROP DEFAULT,
    ALTER COLUMN ${_column} DROP NOT NULL,
    DROP CONSTRAINT IF EXISTS ${_c0},
    DROP CONSTRAINT IF EXISTS ${_c1},
    DROP CONSTRAINT IF EXISTS ${_c2}





ALTER TABLE ${_schema}.${_table} ALTER COLUMN ${_column} TYPE ${_type} USING

    btrim(${_column})::${_type}
    (${_column}->>'link')::${_type}
    jsonb_build_array(${_column}::text)::${_type}

        (CASE WHEN jsonb_array_length(${_column}) = 0 THEN NULL
            ELSE ${_column}->>0 END)::${_type}

    ${_column}::${_type}
